// @ts-strict-ignore
import * as React from "react";
import { ProductCard, ProductCardProps } from "@/core/components/modules/product-card/product-card";
import { ProductListRenderer, ProductGroup } from "./product-list-renderer/product-list-renderer";
import { RestaurantListRenderer, RestaurantGroup } from "./restaurant-list-renderer/restaurant-list-renderer";

function PassDataThrough<T>({ data, children }: ListTransformerProps<T>) {
  return (
    <>
      {React.Children.map(children, (child) => {
        if (!React.isValidElement<ListReceiverProps<T>>(child)) {
          return child;
        }
        return React.cloneElement(child, { data });
      })}
    </>
  );
}

export type ListReceiverProps<T> = {
  data: T[];
};
export type ListTransformerProps<T> = React.PropsWithChildren<ListReceiverProps<T>>;
type ListRenderer<T> = React.ComponentType<ListReceiverProps<T>>;

export type ListBlockBaseProps<T> = {
  renderer: ListRenderer<T>;
  filter?: React.ComponentType<ListTransformerProps<T>>;
  sorter?: React.ComponentType<ListTransformerProps<T>>;
  data: T[];
};

function ListBlockBase<T>({
  renderer: Renderer,
  filter: Filter = PassDataThrough,
  sorter: Sorter = PassDataThrough,
  data = [],
}: ListBlockBaseProps<T>) {
  return (
    <Filter data={data}>
      <Sorter data={undefined}>
        <Renderer data={undefined} />
      </Sorter>
    </Filter>
  );
}

type SpecificRendererIf<T, MatchingType, Renderer> = T extends MatchingType
  ? Omit<ListBlockBaseProps<T>, "renderer"> & {
      renderer: Renderer;
    }
  : never;

export type ListBlockProps<T> =
  | SpecificRendererIf<T, ProductCardProps, "Product">
  | SpecificRendererIf<T, ProductGroup, "ProductGroups">
  | SpecificRendererIf<T, RestaurantGroup, "RestaurantGroups">
  | ListBlockBaseProps<T>;
export function ListBlock<T>({ renderer, filter, sorter, data }: ListBlockProps<T>) {
  switch (renderer) {
    case "Product":
      return (
        <ListBlockBase
          renderer={({ data }) => <>{data?.map((product, idx) => <ProductCard key={idx} {...product} />)}</>}
          filter={filter}
          sorter={sorter}
          data={data}
        />
      );
    case "ProductGroups": {
      return <ListBlockBase renderer={ProductGroupsRenderer} filter={filter} sorter={sorter} data={data} />;
    }
    case "RestaurantGroups": {
      return <ListBlockBase renderer={RestaurantGroupsRenderer} filter={filter} sorter={sorter} data={data} />;
    }
  }
  return <ListBlockBase renderer={renderer} filter={filter} sorter={sorter} data={data} />;
}

const ProductGroupsRenderer = (props) => <ProductListRenderer isExpandableList={false} {...props} />;

const RestaurantGroupsRenderer = (props) => <RestaurantListRenderer isExpandableList={false} {...props} />;
