import { ProductCard, ProductCardProps } from "@/core/components/modules/product-card/product-card";

import BaseListGroupRenderer, {
  BaseListGroupRendererProps,
  ListGroup,
} from "../base-list-group-renderer/base-list-group-renderer";

export type Product = ProductCardProps & {
  id: string;
};

export type ProductGroup<T = object> = ListGroup<Product & T>;

export function ProductListRenderer<T>({
  data,
  isExpandableList,
  className,
}: Omit<BaseListGroupRendererProps<Product & T>, "renderItem">) {
  return (
    <BaseListGroupRenderer
      data={data}
      isExpandableList={isExpandableList}
      renderItem={(productCardProps) => <ProductCard key={productCardProps.id} {...productCardProps} />}
      className={className}
      listVariant="wrap"
    />
  );
}
